const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const year = 2021;
  // Antarctic ozone hole typically develops in austral spring (August-November)
  const startDate = ee.Date.fromYMD(year, 8, 1);
  const endDate = ee.Date.fromYMD(year, 11, 30);

  // Define the Antarctic region (south of 60 degrees S latitude)
  const antarctic = ee.Geometry.Rectangle([-180, -90, 180, -60], null, false);

  // Ozone hole threshold (Dobson Units - DU)
  const OZONE_HOLE_THRESHOLD_DU = 220; // Standard definition for ozone hole

  // 2. Data Acquisition & Check
  // Using NASA's Aura OMI Total Ozone data
  let collection = ee.ImageCollection('NASA/OMI/AURA_L3_OMTO3_V003')
    .filterDate(startDate, endDate)
    .filterBounds(antarctic)
    .select(['total_ozone', 'cloud_fraction']);

  const initialSize = await collection.size().getInfo();
  if (initialSize === 0) {
    console.log(`No OMI images found for ${year} in the Antarctic region.`);
    console.log("C1");
    return;
  }
  console.log(`Initial images for ${year}: ${initialSize}`);

  // Function to calculate ozone hole area for a single image
  const calculateOzoneHoleArea = (image) => {
    // Mask out cloudy pixels (cloud_fraction > 0.3 is generally considered too cloudy for reliable ozone data)
    const cloudMask = image.select('cloud_fraction').lt(0.3);
    const ozone = image.select('total_ozone').updateMask(cloudMask);

    // Identify pixels below the ozone hole threshold (220 DU)
    const ozoneHolePixels = ozone.lt(OZONE_HOLE_THRESHOLD_DU);

    // Calculate the area of these pixels. pixelArea() returns area in square meters.
    const areaImage = ozoneHolePixels.multiply(ee.Image.pixelArea());

    // Reduce the area image over the Antarctic geometry to get total area in square meters
    // Use a reasonable scale to avoid memory issues and timeouts. OMI resolution is ~13x24 km at nadir,
    // so a scale of 25000 is appropriate to get the entire pixel area.
    const stats = areaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: antarctic,
      scale: 25000, // Roughly OMI pixel size
      maxPixels: 1e9,
      crs: 'EPSG:4326', // Ensure consistent CRS for area calculation
    });

    // Get the sum of area in square meters, convert to square kilometers
    const areaSqM = ee.Number(stats.get('total_ozone')).unmask(0);
    const areaSqKm = areaSqM.divide(1e6); // Convert m^2 to km^2

    // Return the image date and calculated area
    return ee.Feature(null, {
      'date': image.date().format('YYYY-MM-dd'),
      'ozone_hole_area_sq_km': areaSqKm,
      'valid_pixels': ozoneHolePixels.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: antarctic,
        scale: 25000,
        maxPixels: 1e9,
      }).get('total_ozone').unmask(0), // Count pixels after thresholding
    });
  };

  // Map the function over the collection
  const areasCollection = collection.map(calculateOzoneHoleArea);

  // Convert to a list to find the maximum area
  const areasList = await areasCollection.filter(ee.Filter.notNull(['ozone_hole_area_sq_km']))
    .select(['ozone_hole_area_sq_km', 'valid_pixels'])
    .sort('ozone_hole_area_sq_km', false) // Sort in descending order to easily get max
    .toList(initialSize); // Get all features

  if (areasList.size().getInfo() === 0) {
    console.log("No images processed with valid ozone hole area after masking.");
    // This could happen if all images are 100% cloudy or have no pixels below the threshold after masking.
    console.log("C2");
    return;
  }

  const maxAreaFeature = ee.Feature(areasList.get(0));
  const maxArea = await maxAreaFeature.get('ozone_hole_area_sq_km').getInfo();
  const maxAreaDate = await maxAreaFeature.get('date').getInfo();
  const validPixelsAtMax = await maxAreaFeature.get('valid_pixels').getInfo();

  if (maxArea === null || isNaN(maxArea)) {
    console.log("Calculation for maximum ozone hole area resulted in an invalid value (null/NaN).");
    console.log("C3");
    return;
  }

  // Define the target size in million square kilometers
  const targetSize_M_sq_km = 18;
  const targetSize_sq_km = targetSize_M_sq_km * 1e6;

  console.log(`Max ozone hole area in ${year}: ${maxArea.toFixed(2)} km² (on ${maxAreaDate}).`);
  console.log(`Valid pixels at max area: ${validPixelsAtMax}`);

  if (validPixelsAtMax === 0) {
    console.log("No valid ozone hole pixels found during the period after all masking.");
    console.log("C2");
    return;
  }

  // Compare the maximum calculated area with the target size
  const reachedTarget = maxArea >= targetSize_sq_km;

  if (reachedTarget) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
